<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { language, setLanguage, t } from '../services/language'
const login = ref(''); const password = ref(''); const loading = ref(false); const error = ref(''); const router = useRouter(); const auth = useAuthStore()
const submit = async () => { loading.value = true; error.value = ''; try { await auth.login({ login: login.value, password: password.value }); router.push('/') } catch (e) { error.value = e.response?.data?.message || 'লগইন করা যায়নি। তথ্য আবার পরীক্ষা করুন।' } finally { loading.value = false } }
</script>
<template><div class="login-page"><section class="login-art"><div class="login-brand"><span>▦</span><strong>Byabsha 360</strong></div><div><p class="eyebrow">COMPLETE BUSINESS CONTROL</p><h1>{{ language === 'en' ? 'Your business,' : 'আপনার ব্যবসা,' }}<br><em>{{ language === 'en' ? 'under your control.' : 'আপনার নিয়ন্ত্রণে।' }}</em></h1><p>{{ language === 'en' ? 'Manage sales, stock, customers, and branches in one place.' : 'বিক্রয়, স্টক, গ্রাহক এবং শাখা—সবকিছু এক জায়গায় পরিচালনা করুন।' }}</p></div><div class="login-stat"><strong>360°</strong><span>Business visibility</span></div></section><section class="login-form"><form @submit.prevent="submit"><label class="language-switch login-language"><span class="sr-only">{{ t('language') }}</span><select :value="language" @change="setLanguage($event.target.value)"><option value="bn">{{ t('bangla') }}</option><option value="en">{{ t('english') }}</option></select></label><p class="eyebrow">ADMIN PORTAL</p><h2>{{ language === 'en' ? 'Welcome back' : 'স্বাগতম ফিরে আসুন' }}</h2><p>{{ t('loginHelp') }}</p><label>{{ t('emailOrMobile') }}<input v-model="login" required placeholder="admin@company.com" /></label><label>{{ t('password') }}<input v-model="password" required type="password" placeholder="••••••••" /></label><p v-if="error" class="error">{{ error }}</p><button class="primary full" :disabled="loading">{{ loading ? (language === 'en' ? 'Logging in...' : 'লগইন হচ্ছে...') : `${t('login')} →` }}</button></form></section></div></template>
